#!/usr/bin/env node
/**
 * Dependency Upgrader — Fix Report Renderer
 *
 * Combines three things into the final deliverable:
 *   .github/.pipeline-context/dependency-upgrader/<id>.patch.diff         — the diff, drafted by the agent
 *   .github/.pipeline-context/dependency-upgrader/<id>.rationale.json    — judgement, written by the agent
 *   .github/.pipeline-context/dependency-upgrader/<id>.verification.json — facts, from apply-version-bump.js
 *
 * Output:
 *   docs/agent_output/04-remediation/fix_<id>.md   — the report (same location + filename pattern 04b-fixer uses)
 *   docs/agent_output/04-remediation/fix_<id>.diff — the raw patch, copied verbatim, directly `git apply`-able
 *
 * Writing to the same location as 04b-fixer means this report shows up in the same shared index
 * without any special-casing downstream — Phase C doesn't need to know or care which of the two
 * Fixer skills produced a given fix_<id>.md.
 *
 * Status in the rendered report reflects the verification record honestly — a failed or refused
 * verification is still rendered, marked as such, never silently upgraded to a pass.
 *
 * Usage:
 *   node scripts/render-fix-report.js --all
 *   node scripts/render-fix-report.js --issue ISSUE-004
 */
const fs = require('fs');
const path = require('path');
const {
  REPO_ROOT, OUT_DIR, OUT_README,
  rel, listApprovedDependencyPlans, resolveFixPlan,
  patchPathFor, rationalePathFor, verificationJsonPathFor, fixReportPathFor, fixDiffPathFor,
} = require('./lib/depfixplans');

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--issue' || arg === '-i') args.issue = argv[++i];
    else if (arg === '--all' || arg === '-a') args.all = true;
    else if (arg === '--help' || arg === '-h') args.help = true;
  }
  return args;
}

function usage() {
  console.log(`Dependency Upgrader — Fix Report Renderer

  node scripts/render-fix-report.js --all
  node scripts/render-fix-report.js --issue <ISSUE-ID>

Options:
  --all, -a     Render every Approved CWE-1104 plan that has a patch + rationale + verification ready
  --issue, -i   A single issue id, e.g. ISSUE-004
  --help, -h    Show this message`);
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const REQUIRED = [
  ['summary', (r) => typeof r.summary === 'string' && r.summary.trim()],
  ['files_changed (non-empty array)', (r) => Array.isArray(r.files_changed) && r.files_changed.length > 0],
  ['matches_plan (boolean)', (r) => typeof r.matches_plan === 'boolean'],
  ['deviations (required when matches_plan is false)', (r) => r.matches_plan || (Array.isArray(r.deviations) && r.deviations.length > 0)],
];

function validate(rationale) {
  const missing = REQUIRED.filter(([, check]) => !check(rationale)).map(([key]) => key);
  if (missing.length) {
    throw new Error(`Rationale JSON is missing required field(s):\n  - ${missing.join('\n  - ')}\nSee templates/rationale.schema.json for the expected shape.`);
  }
}

// ---------------------------------------------------------------------------
// Rendering helpers
// ---------------------------------------------------------------------------

function bullets(items, emptyText = '_none recorded_') {
  if (!items || !items.length) return [emptyText];
  return items.map((i) => `- ${i}`);
}

// Depth-independent: derived from where the report is actually written.
const UP_TO_ROOT = path.relative(OUT_DIR, REPO_ROOT).replace(/\\/g, '/');

function linkFromOutput(repoRelativePath, label) {
  return `[${label || repoRelativePath}](${`${UP_TO_ROOT}/${repoRelativePath}`.replace(/\\/g, '/')})`;
}

function statusOf(verification) {
  if (verification.refused) return 'Refused — plan not Approved';
  return verification.passed ? 'Compiled' : 'Compile Failed';
}

// ---------------------------------------------------------------------------
// Report
// ---------------------------------------------------------------------------

function render(plan, rationale, verification, patchText) {
  const status = statusOf(verification);
  const dep = plan.dependencyUpgrade || {};
  const out = [];

  out.push(`# Fix — ${plan.id}`);
  out.push('');
  out.push(`## ${plan.title}`);
  out.push('');
  out.push(`> ${rationale.summary.trim()}`);
  out.push('');
  out.push(`_Generated by the Dependency Upgrader (04_fix-generator Stage 2) on ${new Date().toISOString().slice(0, 10)}. Verification run ${verification.generatedAt || 'not recorded'}._`);
  out.push('');

  out.push('## At a glance');
  out.push('');
  out.push('| | |');
  out.push('|---|---|');
  out.push(`| **Status** | ${status} |`);
  out.push(`| **CWE** | \`CWE-1104\` |`);
  out.push(`| **Fix plan** | ${linkFromOutput(plan.relativePlanFile, plan.relativePlanFile)} |`);
  out.push(`| **Dependency** | \`${dep.mavenCoordinate || 'n/a'}\` ${dep.currentVersion || '?'} → ${verification.declaredVersion || '?'} (target ≥${dep.minimumFixedVersion || '?'}) |`);
  out.push(`| **Verification level** | ${verification.level || 'not run'} |`);
  out.push(`| **Matches plan** | ${rationale.matches_plan ? 'yes' : 'no — see Deviations'} |`);
  out.push(`| **Patch** | ${linkFromOutput(rel(fixDiffPathFor(plan.id)), path.basename(fixDiffPathFor(plan.id)))} |`);
  out.push('');

  out.push('## 1. What changed');
  out.push('');
  out.push(rationale.summary.trim());
  out.push('');
  out.push('| File | Change |');
  out.push('|---|---|');
  for (const f of rationale.files_changed) {
    out.push(`| ${linkFromOutput(f.file, f.file.split('/').pop())} | ${(f.change || '').replace(/\|/g, '\\|')} |`);
  }
  out.push('');

  out.push('## 2. The diff');
  out.push('');
  out.push(`Also written as a standalone, directly \`git apply\`-able file at \`${rel(fixDiffPathFor(plan.id))}\`.`);
  out.push('');
  out.push('```diff');
  out.push(patchText.trimEnd());
  out.push('```');
  out.push('');

  out.push('## 3. Why this is the minimum correct version bump');
  out.push('');
  out.push(plan.approach ? plan.approach : '_Fix plan approach text not available — see the linked plan._');
  out.push('');

  if (!rationale.matches_plan) {
    out.push('## 4. Deviations from the plan');
    out.push('');
    bullets(rationale.deviations, '_None recorded — but matches_plan is false; the rationale should explain why._').forEach((b) => out.push(b));
    out.push('');
  }

  const sectionN = rationale.matches_plan ? 4 : 5;
  out.push(`## ${sectionN}. Dependency verification evidence`);
  out.push('');
  if (verification.refused) {
    out.push(`**Refused before any verification ran:** ${verification.reason}`);
  } else {
    out.push(`Result: **${verification.passed ? 'PASS' : 'FAIL'}** at stage \`${verification.stage}\`, run inside an isolated \`git worktree\` (applied and removed — the real working tree was never touched).`);
    out.push('');
    out.push('| Check | Result |');
    out.push('|---|---|');
    out.push(`| Declared version in patched pom.xml | ${verification.declaredVersion ? `\`${verification.declaredVersion}\` (${verification.declaredIn})` : 'not reached'} |`);
    out.push(`| Compiles | ${verification.stage === 'compile' ? 'FAIL' : (verification.steps && verification.steps.length ? 'yes' : 'not reached')} |`);
    out.push(`| Resolved version (\`mvn dependency:tree\`) | ${verification.resolvedVersion ? `\`${verification.resolvedVersion}\` (${verification.resolvedIn})` : 'not reached'} |`);
    out.push(`| Target | \`>= ${verification.minimumFixedVersion}\` |`);
    out.push('');
    if (verification.modules) out.push(`Modules built: ${verification.modules.map((m) => `\`${m}\``).join(', ')}`);
    out.push('');
    if (verification.output) {
      out.push('<details><summary>Failure detail</summary>');
      out.push('');
      out.push('```');
      out.push(verification.output);
      out.push('```');
      out.push('');
      out.push('</details>');
      out.push('');
    }
    if (verification.steps && verification.steps.length) {
      out.push('<details><summary>Per-step output</summary>');
      out.push('');
      for (const s of verification.steps) {
        out.push(`**${s.command}** — exit code ${s.exitCode}`);
        out.push('');
        out.push('```');
        out.push(s.output);
        out.push('```');
        out.push('');
      }
      out.push('</details>');
      out.push('');
    }
  }
  out.push('');
  out.push('_"Compiled" here means: the declared version meets the target, the module compiles, and the '
    + '*resolved* dependency-tree version also meets the target — stronger than a plain compile check, '
    + 'but still not a merge signal. Only Phase C\'s merge arbiter '
    + '(`docs/agent_output/07-ship/verdict_<id>.md`) can clear a patch to ship._');
  out.push('');

  out.push(`## ${sectionN + 1}. Residual risk`);
  out.push('');
  bullets(rationale.residual_risk, '_None recorded._').forEach((b) => out.push(b));
  out.push('');

  if (rationale.open_questions && rationale.open_questions.length) {
    out.push(`## ${sectionN + 2}. Open questions`);
    out.push('');
    bullets(rationale.open_questions).forEach((b) => out.push(b));
    out.push('');
  }

  out.push('## How to apply this patch');
  out.push('');
  out.push('```powershell');
  out.push(`git apply ${rel(fixDiffPathFor(plan.id))}`);
  out.push('```');
  out.push('');
  out.push('Review the diff above before applying — this report is evidence for a human decision, not an auto-merge.');
  out.push('');

  out.push('---');
  out.push('');
  out.push('The diff, the file list and the verification evidence are rendered verbatim from the '
    + 'patch and the isolated build. The summary, the deviation notes and the residual risk are the '
    + 'judgement of the Dependency Upgrader agent.');
  out.push('');

  return out.join('\n');
}

// ---------------------------------------------------------------------------
// Index — identical scan/write logic to 04a/04b's, so re-running either always converges on the
// same content for docs/agent_output/04-remediation/README.md regardless of which one ran last.
// ---------------------------------------------------------------------------

const INDEX_MARKER = '<!-- AUTO-GENERATED TABLE — regenerated by 04_fix-generator (plan + fix), do not hand-edit below this line -->';

function rewriteIndex() {
  if (!fs.existsSync(OUT_DIR)) return;
  const ids = new Set();
  for (const f of fs.readdirSync(OUT_DIR)) {
    const m = /^fix_plan_(.+)\.md$/i.exec(f) || /^fix_(?!plan_)(.+)\.md$/i.exec(f);
    if (m) ids.add(m[1]);
  }
  const rows = [...ids].sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).map((id) => {
    const planFile = path.join(OUT_DIR, `fix_plan_${id}.md`);
    const fixFile = path.join(OUT_DIR, `fix_${id}.md`);
    const planText = fs.existsSync(planFile) ? fs.readFileSync(planFile, 'utf8') : null;
    const fixText = fs.existsSync(fixFile) ? fs.readFileSync(fixFile, 'utf8') : null;
    const titleMatch = (planText && /^##\s+(.+)$/m.exec(planText)) || (fixText && /^##\s+(.+)$/m.exec(fixText));
    const cweMatch = planText && /\|\s*\*\*CWE\*\*\s*\|\s*`([^`]+)`/.exec(planText);
    const planStatusMatch = planText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(planText);
    const fixStatusMatch = fixText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(fixText);
    return {
      id,
      title: titleMatch ? titleMatch[1].trim() : '(untitled)',
      cwe: cweMatch ? cweMatch[1].trim() : '-',
      planStatus: planText ? (planStatusMatch ? planStatusMatch[1].trim() : 'unknown') : '_pending_',
      fixStatus: fixText ? (fixStatusMatch ? fixStatusMatch[1].trim() : 'unknown') : '_pending_',
      planFile: planText ? `fix_plan_${id}.md` : null,
      fixFile: fixText ? `fix_${id}.md` : null,
    };
  });

  const existing = fs.existsSync(OUT_README) ? fs.readFileSync(OUT_README, 'utf8') : defaultReadmeContract();
  const contract = existing.includes(INDEX_MARKER) ? existing.slice(0, existing.indexOf(INDEX_MARKER)) : existing.trimEnd() + '\n\n';

  const table = [INDEX_MARKER, ''];
  if (!rows.length) {
    table.push('_No fix plans or fixes yet — run the Fix Generator agent against a root cause report._', '');
  } else {
    table.push('| ID | Title | CWE | Plan Status | Fix Status | Plan | Fix |', '|---|---|---|---|---|---|---|');
    for (const r of rows) {
      const planLink = r.planFile ? `[${r.planFile}](./${r.planFile})` : '_none_';
      const fixLink = r.fixFile ? `[${r.fixFile}](./${r.fixFile})` : '_none_';
      table.push(`| ${r.id} | ${r.title} | \`${r.cwe}\` | ${r.planStatus} | ${r.fixStatus} | ${planLink} | ${fixLink} |`);
    }
    table.push('');
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_README, contract.trimEnd() + '\n\n' + table.join('\n'));
}

function defaultReadmeContract() {
  return `# Remediation

Fix plans and compiled patches produced by the **Fix Generator** agent (\`04_fix-generator\`), one
pair per diagnosed defect in [\`docs/agent_output/02-root-cause/\`](../02-root-cause/):

- **\`fix_plan_<id>.md\`** — Stage 1's remediation strategy, citing a CWE-aligned pattern from
  [\`.github/skills/04a-fix-strategist/catalog/cwe-patterns.json\`](../../.github/skills/04a-fix-strategist/catalog/cwe-patterns.json).
  Never contains a diff. Starts at **Status: Proposed**.
- **\`fix_<id>.md\` + \`fix_<id>.diff\`** — Stage 2's compiled patch, drafted only once a human edits
  the plan's Status to **Approved**. The diff is a standalone, directly \`git apply\`-able patch —
  Stage 2 never edits the real working tree itself. Written by \`04b-fixer\` for a code-logic fix, or
  by \`04c-dependency-upgrader\` for a \`CWE-1104\` dependency-version fix — same output location and
  Status vocabulary either way.

## The approval checkpoint

Every plan starts with **Status: Proposed**. Stage 2 will not act on a plan until a human edits that
Status cell in the plan's own file to **Approved** (or to **Rejected** to close it out). This is a
deliberate pause point between choosing a remediation strategy and writing code.

## A Compiled patch is not a merge signal

It only means the module builds (and, for a dependency upgrade, that the resolved version also meets
the target). Whether the patch actually closes the vulnerability, survives adversarial re-testing,
passes a real test/build gate, and is safe to ship is decided by the rest of the pipeline — see
[\`docs/agent_output/07-ship/\`](../07-ship/) for the final verdict.

## Reading Fix Status

- **Compiled** — the patch applied cleanly and the affected module compiled (and, if a target test
  was named, passed it) inside an isolated \`git worktree\`. For a dependency upgrade, this also means
  the resolved \`dependency:tree\` version met the plan's target.
- **Compile Failed** — the patch was drafted but did not apply cleanly, or the build/version check
  failed. The report and diff are still published for review; do not apply a patch marked this way.
- **Refused** — Stage 2 would not act because the plan was not \`Status: Approved\` at the time (or,
  for \`04c-dependency-upgrader\`, because the plan's CWE was not \`CWE-1104\`).

## Pipeline state

Run \`node .github/skills/04a-fix-strategist/scripts/list-remediation-workload.js\`,
\`node .github/skills/04b-fixer/scripts/list-fix-workload.js\`, or
\`node .github/skills/04c-dependency-upgrader/scripts/list-fix-workload.js\` for the live pipeline
state — this table is for humans; the pipeline itself discovers plans and fixes by scanning
\`docs/agent_output/04-remediation/fix_plan_*.md\` and \`fix_*.md\`.

`;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function renderOne(id) {
  const plan = resolveFixPlan(id);

  const rationaleFile = rationalePathFor(plan.id);
  if (!fs.existsSync(rationaleFile)) {
    throw new Error(`No rationale file at ${rel(rationaleFile)}. Draft the patch and write the rationale JSON first, following templates/rationale.schema.json.`);
  }
  let rationale;
  try {
    rationale = JSON.parse(fs.readFileSync(rationaleFile, 'utf8'));
  } catch (err) {
    throw new Error(`Rationale file ${rel(rationaleFile)} is not valid JSON: ${err.message}`);
  }
  validate(rationale);
  if (rationale.issue_id && rationale.issue_id !== plan.id) {
    throw new Error(`Rationale is for ${rationale.issue_id} but the fix plan is ${plan.id}.`);
  }

  const verificationFile = verificationJsonPathFor(plan.id);
  if (!fs.existsSync(verificationFile)) {
    throw new Error(`No verification record at ${rel(verificationFile)}. Run apply-version-bump.js --issue ${plan.id} first.`);
  }
  const verification = JSON.parse(fs.readFileSync(verificationFile, 'utf8'));

  const patchFile = patchPathFor(plan.id);
  if (!fs.existsSync(patchFile)) {
    throw new Error(`No patch at ${rel(patchFile)}. It should exist before verification even ran — re-check the agent's steps.`);
  }
  const patchText = fs.readFileSync(patchFile, 'utf8');

  const reportTarget = fixReportPathFor(plan.id);
  const diffTarget = fixDiffPathFor(plan.id);
  fs.mkdirSync(path.dirname(reportTarget), { recursive: true });
  fs.writeFileSync(diffTarget, patchText);
  fs.writeFileSync(reportTarget, render(plan, rationale, verification, patchText));

  return {
    id: plan.id,
    status: statusOf(verification),
    report: rel(reportTarget),
  };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) return usage();

  if (args.all) {
    const targets = listApprovedDependencyPlans();
    if (!targets.length) throw new Error('No Approved CWE-1104 fix plans found. Nothing to render.');

    const written = [];
    const skipped = [];
    for (const t of targets) {
      try {
        const result = renderOne(t.id);
        written.push(result);
        console.log(`${result.id.padEnd(10)} ${result.status.padEnd(20)} -> ${result.report}`);
      } catch (err) {
        skipped.push({ id: t.id, reason: err.message.split('\n')[0] });
        console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`);
      }
    }

    rewriteIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s) to ${rel(OUT_DIR)}.`);
    if (skipped.length) {
      console.log(`Still pending: ${skipped.map((s) => s.id).join(', ')}`);
      process.exitCode = 1;
    }
    return;
  }

  if (!args.issue) {
    throw new Error('Missing --issue. Pass an issue id (--issue ISSUE-004) or --all to render every Approved CWE-1104 plan.');
  }
  const result = renderOne(args.issue);
  rewriteIndex();
  console.log(`Dependency Upgrader — wrote ${result.report}`);
  console.log(`  issue  : ${result.id}`);
  console.log(`  status : ${result.status}`);
}

try {
  main();
} catch (err) {
  console.error('Rendering failed:', err.message);
  process.exit(1);
}
